-- Column descriptions of the application schema (generated by tools/gen_column_comments.py from the comments in 06_app_schema.sql)
\set ON_ERROR_STOP on
COMMENT ON COLUMN public.users.password_hash IS 'bcrypt ($2a$/$2b$), written by the backend only';
COMMENT ON COLUMN public.users.is_active IS 'false = deactivated (soft delete); never hard-delete health data owners';
COMMENT ON COLUMN public.users.is_demo IS 'true for the seeded demo accounts';
COMMENT ON COLUMN public.users.two_factor_secret IS 'TOTP secret, encrypted by the backend';
COMMENT ON COLUMN public.patient_profiles.target_min_mgdl IS 'time-in-range window';
COMMENT ON COLUMN public.patient_profiles.hypo_threshold_mgdl IS 'alert when glucose <= this  (report: <= 70)';
COMMENT ON COLUMN public.patient_profiles.hyper_threshold_mgdl IS 'alert when glucose >= this  (report: >= 180)';
COMMENT ON COLUMN public.patient_profiles.urgent_low_mgdl IS 'emergency alert';
COMMENT ON COLUMN public.patient_profiles.research_patient_id IS 'provenance of demo patients (research.patients.patient_id)';
COMMENT ON COLUMN public.care_relationships.can_add_recommendations IS 'clinicians only in practice';
COMMENT ON COLUMN public.treatment_plans.target_glucose_min IS 'report: target_glucose ''90-130 mg/dL''';
COMMENT ON COLUMN public.treatment_plans.prescribed_insulin IS 'report: prescribed_insulin (type and dosage, free text)';
COMMENT ON COLUMN public.user_settings.font_scale IS 'WCAG: large fonts';
COMMENT ON COLUMN public.refresh_tokens.token_hash IS 'store a hash, never the token';
COMMENT ON COLUMN public.device_tokens.token IS 'Firebase Cloud Messaging registration token';
COMMENT ON COLUMN public.food_catalog.name IS 'machine name, e.g. apple_pie (= Food-101 class name)';
COMMENT ON COLUMN public.food_catalog.is_verified IS 'false = rough estimate, do not use for dosing decisions';
COMMENT ON COLUMN public.food_catalog.research_class_id IS 'research.food_classes.class_id (photo model label)';
COMMENT ON COLUMN public.glucose_logs.glucose_value IS 'mg/dL (report: INT, app validates 0-500)';
COMMENT ON COLUMN public.glucose_logs.client_uuid IS 'generated by the mobile app: idempotent offline sync';
COMMENT ON COLUMN public.glucose_logs.deleted_at IS 'soft delete (sync)';
COMMENT ON COLUMN public.lab_results.unit IS '''%'' (HbA1c, NGSP), ''mg/dL'', ''mmol/L''';
COMMENT ON COLUMN public.medications.dosage IS 'text as in the report, e.g. ''500 mg'' or ''10 units''';
COMMENT ON COLUMN public.reminders.medication_name IS 'report Reminder.medication_name';
COMMENT ON COLUMN public.reminders.dosage IS 'report Reminder.dosage';
COMMENT ON COLUMN public.reminders.scheduled_time IS 'local time of day in `timezone`';
COMMENT ON COLUMN public.alerts.follow_up_due_at IS '"follow-up prompt after an abnormal reading"';
COMMENT ON COLUMN public.reports.summary IS 'statistics snapshot (see fn_glucose_summary)';
COMMENT ON COLUMN public.ai_messages.intent IS 'LOG_GLUCOSE, LOG_INSULIN, LOG_MEAL, UNKNOWN ... (Dia NLP service)';
COMMENT ON COLUMN public.ai_messages.created_entity_type IS 'e.g. GLUCOSE_LOG';
COMMENT ON COLUMN public.audit_logs.user_id IS 'who acted';
COMMENT ON COLUMN public.audit_logs.patient_id IS 'whose data was touched (no FK: history must outlive the patient row)';
COMMENT ON COLUMN public.audit_logs.action IS 'LOGIN, LOGIN_FAILED, VIEW_PATIENT_DATA, SHARE_GRANTED, EXPORT_REPORT ...';
